//! Windowed A* with exit-through-edge semantics.
//!
//! The search may finish either on a goal tile inside the window, or by
//! "leaving" through an edge tile, paying the caller's heuristic for the rest
//! of the way. With the static distance field as heuristic (exact for
//! unweighted terrain, so admissible for costs ≥ STEP per tile), this gives a
//! danger-aware first step towards far-away goals at window cost.

use crate::bc_path::window::{Window, BLOCKED, CELLS};
use crate::bc_core::geom::DIRS8;
use crate::bc_core::Pos;
use std::cmp::Reverse;
use std::collections::BinaryHeap;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SearchResult {
    /// First tile to step onto (absolute position), or the start if already at a goal.
    pub first_step: Pos,
    pub total_cost: u32,
    pub expanded: u32,
}

/// `costs[i]` is the cost of entering window cell `i` (`BLOCKED` = impassable).
/// `is_goal` marks terminal tiles; `exit_cost(p)` estimates the remaining cost
/// from an edge tile `p` (return `None` if leaving there makes no progress).
///
/// `max_expansions` bounds the work: in game each expansion costs roughly
/// 500–700 fuel (heap operations over eight neighbours), so the caller sizes
/// it from the fuel left this turn. When the cap is hit, the best terminal
/// found so far is returned (or `None`).
pub fn search(
    win: &Window,
    costs: &[u16; CELLS],
    start: Pos,
    is_goal: &dyn Fn(Pos) -> bool,
    exit_cost: &dyn Fn(Pos) -> Option<u32>,
    heuristic: &dyn Fn(Pos) -> u32,
    max_expansions: u32,
) -> Option<SearchResult> {
    let start_i = win.index(start)?;
    let mut g = [u32::MAX; CELLS];
    let mut parent = [u16::MAX; CELLS];
    let mut heap = BinaryHeap::new();
    g[start_i] = 0;
    heap.push(Reverse((heuristic(start), 0u32, start_i as u16)));
    let mut best: Option<(u32, usize)> = None;
    let mut expanded = 0;

    while let Some(Reverse((f, gc, i))) = heap.pop() {
        let i = i as usize;
        if gc > g[i] {
            continue;
        }
        if best.is_some_and(|(b, _)| f >= b) || expanded >= max_expansions {
            break;
        }
        expanded += 1;
        let p = win.pos(i);
        if is_goal(p) {
            if best.is_none_or(|(b, _)| gc < b) {
                best = Some((gc, i));
            }
            continue;
        }
        if win.on_edge(p) && i != start_i {
            if let Some(rest) = exit_cost(p) {
                let total = gc + rest;
                if best.is_none_or(|(b, _)| total < b) {
                    best = Some((total, i));
                }
            }
        }
        for d in DIRS8 {
            let n = p + d;
            let Some(ni) = win.index(n) else { continue };
            let c = costs[ni];
            if c == BLOCKED {
                continue;
            }
            let ng = gc + u32::from(c);
            if ng < g[ni] {
                g[ni] = ng;
                parent[ni] = i as u16;
                heap.push(Reverse((ng + heuristic(n), ng, ni as u16)));
            }
        }
    }

    let (total_cost, mut end) = best?;
    if end == start_i {
        return Some(SearchResult { first_step: start, total_cost, expanded });
    }
    while parent[end] as usize != start_i {
        end = parent[end] as usize;
        if end == u16::MAX as usize {
            return None;
        }
    }
    Some(SearchResult { first_step: win.pos(end), total_cost, expanded })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::bc_path::danger::{fill_costs, DangerParams, Threat, STEP};
    use crate::bc_core::Terrain;

    fn costs_for(t: &Terrain, threats: &[Threat]) -> (Window, [u16; CELLS]) {
        let win = Window { origin: Pos::new(0, 0) };
        let mut costs = [0u16; CELLS];
        fill_costs(&win, t, &|_| false, threats, DangerParams::default(), &mut costs);
        (win, costs)
    }

    #[test]
    fn finds_goal_inside_window() {
        let t = Terrain::from_ascii(&["...#...", "...#...", "......."]);
        let (win, costs) = costs_for(&t, &[]);
        let goal = Pos::new(6, 0);
        let r = search(
            &win,
            &costs,
            Pos::new(0, 0),
            &|p| p == goal,
            &|_| None,
            &|p| u32::from(STEP) * p.cheb(goal) as u32,
            1000,
        )
        .unwrap();
        // (0,0) → (1,0) → (2,1) → (3,2) → (4,1) → (5,0) → (6,0)
        assert_eq!(r.total_cost, u32::from(STEP) * 6, "diagonally under the wall");
        assert_eq!(Pos::new(0, 0).cheb(r.first_step), 1);
    }

    #[test]
    fn detours_around_danger_when_cheaper() {
        let t = Terrain::from_ascii(&[".......", ".......", "......."]);
        let threat = Threat { pos: Pos::new(3, 0), range: 1, dps: 400.0 };
        let (win, costs) = costs_for(&t, &[threat]);
        let goal = Pos::new(6, 0);
        let r = search(
            &win,
            &costs,
            Pos::new(0, 0),
            &|p| p == goal,
            &|_| None,
            &|p| u32::from(STEP) * p.cheb(goal) as u32,
            1000,
        )
        .unwrap();
        // Straight line costs 3 danger tiles × 100; the row-2 detour is ~2 tiles longer.
        assert!(r.total_cost < u32::from(STEP) * 6 + 100, "{r:?}");
        assert_eq!(r.first_step.y, 1, "starts moving away from the threat row");
    }

    #[test]
    fn exits_through_edge_using_heuristic() {
        let t = Terrain::from_ascii(&vec!["..............................."; 15]);
        let (win, costs) = costs_for(&t, &[]);
        // Goal far to the east, outside the window.
        let goal = Pos::new(30, 7);
        let h = |p: Pos| u32::from(STEP) * p.cheb(goal) as u32;
        let r = search(&win, &costs, Pos::new(7, 7), &|p| p == goal, &|p| Some(h(p)), &h, 1000)
            .unwrap();
        assert_eq!(r.first_step.x, 8, "heads east");
        assert_eq!(r.total_cost, h(Pos::new(7, 7)));
    }

    #[test]
    fn already_at_goal() {
        let t = Terrain::from_ascii(&["..."]);
        let (win, costs) = costs_for(&t, &[]);
        let r =
            search(&win, &costs, Pos::new(1, 0), &|p| p == Pos::new(1, 0), &|_| None, &|_| 0, 1000)
                .unwrap();
        assert_eq!(r.first_step, Pos::new(1, 0));
        assert_eq!(r.total_cost, 0);
    }
}
